DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.submit_quotation_revision(uuid,text)'::regprocedure) INTO def; def:=replace(def,'COALESCE((SELECT elem FROM jsonb_array_elements(payload->''sections'') elem WHERE elem->>''id''=section->>''id'' LIMIT 1),section)||jsonb_build_object(''repairs'',repairs)','jsonb_build_object(''photos'',''[]''::jsonb,''final_observation'',NULL)||COALESCE((SELECT elem FROM jsonb_array_elements(payload->''sections'') elem WHERE elem->>''id''=section->>''id'' LIMIT 1),section)||jsonb_build_object(''repairs'',repairs)'); def:=replace(def,'base:=owner_total+tenant_total;','owner_total:=round(owner_total); tenant_total:=round(tenant_total); base:=owner_total+tenant_total;'); def:=replace(def,'d:=base*COALESCE((payload->''discount''->>''value'')::numeric,0)/100;','d:=round(base*least(100,greatest(0,COALESCE((payload->''discount''->>''value'')::numeric,0)))/100);'); def:=replace(def,'d:=COALESCE((payload->''discount''->>''value'')::numeric,(payload->''discount''->>''amount'')::numeric,0);','d:=round(COALESCE((payload->''discount''->>''value'')::numeric,(payload->''discount''->>''amount'')::numeric,0));'); def:=replace(def,'owner_d:=CASE WHEN base=0 THEN 0 ELSE d*owner_total/base END; tenant_d:=d-owner_d;','tenant_d:=CASE WHEN base=0 THEN 0 ELSE round(d*tenant_total/base) END; owner_d:=d-tenant_d;'); def:=replace(def,'tax:=round((base-d)*COALESCE((payload->''tax_config''->>''percentage'')::numeric,0)/100);','tax:=round((owner_total-owner_d)*COALESCE((payload->''tax_config''->>''percentage'')::numeric,0)/100)+round((tenant_total-tenant_d)*COALESCE((payload->''tax_config''->>''percentage'')::numeric,0)/100);'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.guard_revision_publication() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.quotation_work_order_revisions WHERE inspection_id=NEW.inspection_id AND status='awaiting_approval') THEN RAISE EXCEPTION 'quotation_change_awaiting_approval'; END IF; IF current_user NOT IN ('postgres','service_role','supabase_admin') AND EXISTS(SELECT 1 FROM public.inspection_work_orders WHERE inspection_id=NEW.inspection_id) THEN RAISE EXCEPTION 'use_quotation_revision'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.protect_paused_work_item() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.repair_item_id IS DISTINCT FROM OLD.repair_item_id OR NEW.work_order_id IS DISTINCT FROM OLD.work_order_id THEN RAISE EXCEPTION 'work_item_identity_is_immutable'; END IF; IF (OLD.quotation_paused OR OLD.is_archived) AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'quotation_change_awaiting_approval'; END IF; IF current_user NOT IN ('postgres','service_role','supabase_admin') AND (NEW.quotation_paused IS DISTINCT FROM OLD.quotation_paused OR NEW.is_archived IS DISTINCT FROM OLD.is_archived) THEN RAISE EXCEPTION 'not_authorized'; END IF; END IF; IF TG_OP IN ('INSERT','DELETE') AND current_user NOT IN ('postgres','service_role','supabase_admin') THEN RAISE EXCEPTION 'use_quotation_revision'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;